#!/bin/bash
# Task 175-w19-convert -- meshsim sim/ WORKER19 (branch sim-w19 11e9173; D42).
# convert_delivery (sim/tools/delivery, v1.3's ConvertDelivery in C++) on the runner: W9's deliveries (v1.25 records)
# converted, the selected windows (w9-deliveries-selected) and every window of evm-zone-29 and cyclone-29. Checked
# against v1.3's ConvertDelivery as Quests 105-107 and 164 ran it: (1) each converted manifest's sha256 equals the one
# they recorded (the manifest lists every converted record's sha256 and size, so this is every record's bytes too);
# (2) every converted record on disk has a sha256 the manifest lists, and their count is right; (3) every link points
# at the source file of the same name. No Java. Not timing. From an embedded kit. Writes only results/175-w19-convert/.
# Scratch in /tmp, removed first and at the end; the deliveries are only read. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/175-w19-convert; mkdir -p "$RES"
W=/tmp/w19-175; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "8e583fc6e6e2400b70088b3f729657c629162e277db9e0115fdfde344c674b71" ] || { echo "kit sha256 mismatch (want 8e583fc6e6e2400b70088b3f729657c629162e277db9e0115fdfde344c674b71)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
DATA=/home/questrunner/data; [ -d "$DATA/w9-deliveries" ] || DATA=$REPO/data
D9=$DATA/w9-deliveries; SEL=$DATA/w9-deliveries-selected
FAIL=0
sec() { echo; echo "==== $* ($(date -u +%T))"; }
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs; $(clang++ --version | head -1)"

sec "inputs"
OKIN=1
declare -A M9=([evm-zone-29]=7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f [cyclone-29]=f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982)
for P in evm-zone-29 cyclone-29; do
  h=$(sha256sum "$D9/$P.manifest.json" 2>/dev/null | cut -d' ' -f1)
  [ "$h" = "${M9[$P]}" ] && [ "$(cut -d' ' -f1 "$D9/$P.COMPLETE" 2>/dev/null)" = "$h" ] || { echo "$P: delivery manifest missing or differs ($h)"; OKIN=0; }
done
[ $OKIN = 1 ] && verdict inputs PASS || { verdict inputs FAIL; exit 1; }

sec "build (clang release, the Makefile's flags)"
( cd "$KS" && clang++ -std=c++20 -fno-exceptions -fno-rtti -Wall -Wextra -Werror -Isrc -pthread -O2 -DNDEBUG \
    tools/delivery/convert_delivery.cpp tests/sha256.cpp src/base/*.cpp src/*.cpp -o "$W/convert_delivery" \
    -Wl,--wrap=malloc,--wrap=calloc,--wrap=realloc,--wrap=free,--wrap=aligned_alloc,--wrap=posix_memalign ) > "$RES/build.log" 2>&1 \
  && verdict build PASS || { tail -20 "$RES/build.log"; verdict build FAIL; exit 1; }

# v1.3's ConvertDelivery's manifests' sha256: 164 (sim/ref's), equal to 105 (evm) and 107 (cyclone) (v1.26.1's)
declare -A WANT=([sel-evm-zone-29]=0a8c8f747bdd8c99d06ed9227718d232458b32fab31be11e932a00060d07580d
                 [sel-cyclone-29]=c003780b5401f3cc7c393a5eac210f83f573b2a79faf7234ab326706f94f8942
                 [full-evm-zone-29]=5bffa524ed8901f1957e546385697e463bc2ddce5b00d81d698ad8cb4078a0aa
                 [full-cyclone-29]=2d5e368e5721dcc0b07997a76a1834b98b998ad1d49bfed9a27ee42ede333bd5)
declare -A NREC=([sel-evm-zone-29]=48 [sel-cyclone-29]=52 [full-evm-zone-29]=32768 [full-cyclone-29]=32768)
declare -A NLNK=([sel-evm-zone-29]=88 [sel-cyclone-29]=95 [full-evm-zone-29]=57348 [full-cyclone-29]=57348)
for S in sel full; do
  [ $S = sel ] && SRC=$SEL || SRC=$D9
  for P in evm-zone-29 cyclone-29; do
    sec "$S $P"
    mf=""; for m in "$SRC/$P.manifest.json" "$SRC/$P/manifest.json" "$SRC/manifest.json"; do [ -f "$m" ] && { mf=$m; break; }; done
    DST=$W/$S; t0=$(date +%s)
    "$W/convert_delivery" "$SRC" "$DST" "$P" --manifest "$mf" > "$RES/convert-$S-$P.log" 2>&1; rc=$?
    cat "$RES/convert-$S-$P.log"; echo "($(( $(date +%s) - t0 )) s)"
    [ $rc = 0 ] || { verdict "convert-$S-$P" FAIL; continue; }
    h=$(sha256sum "$DST/$P.manifest.json" | cut -d' ' -f1)
    [ "$h" = "${WANT[$S-$P]}" ] && verdict "manifest-$S-$P" PASS || { echo "manifest $h, v1.3's ${WANT[$S-$P]}"; cp "$DST/$P.manifest.json" "$RES/$S-$P.manifest.json"; verdict "manifest-$S-$P" FAIL; }
    (cd "$DST/$P" && find . -maxdepth 1 -type f -name 'window_*.bin' | sort | xargs sha256sum) > "$W/recs"
    n=$(wc -l < "$W/recs"); miss=0
    cut -d' ' -f1 "$W/recs" | sort -u > "$W/hs"; grep -oE '[0-9a-f]{64}' "$DST/$P.manifest.json" | sort -u > "$W/mh"
    miss=$(comm -23 "$W/hs" "$W/mh" | wc -l)
    echo "records $n (want ${NREC[$S-$P]}), sha256 not in the manifest: $miss"
    [ "$n" = "${NREC[$S-$P]}" ] && [ "$miss" = 0 ] && verdict "records-$S-$P" PASS || verdict "records-$S-$P" FAIL
    nl=0; badl=0
    while IFS= read -r l; do nl=$((nl + 1)); [ "$(readlink "$l")" = "$(cd "$SRC/$P" && pwd)/$(basename "$l")" ] || badl=$((badl + 1)); done < <(find "$DST/$P" -maxdepth 1 -type l)
    echo "links $nl (want ${NLNK[$S-$P]}), wrong targets: $badl"
    [ "$nl" = "${NLNK[$S-$P]}" ] && [ $badl = 0 ] && verdict "links-$S-$P" PASS || verdict "links-$S-$P" FAIL
    rm -rf "$DST"
  done
done

sec "summary"
cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo ALL_PASS; touch "$RES/ALL_PASS"; exit 0; } || { echo SOME_FAIL; exit 1; }
